with settings as materialized (select $source_corrections102${"schema":"wg-tv-source-corrections102-v1","source":{"id":16,"url":"https://paizo.com/products/btq02eav?Pathfinder-Treasure-Vault","keys":null,"name":"Treasure Vault","group":"pathfinder-core","user_id":null,"meta_data":{"counts":{"feat":54,"item":1123,"spell":1,"trait":24,"action":3,"creature":2,"archetype":2,"content_update":1092}},"created_at":"2024-04-18T08:00:06.877246+00:00","deprecated":null,"foundry_id":"Pathfinder Treasure Vault","operations":null,"artwork_url":null,"description":"Pathfinder Treasure Vault reveals the glittering hoard of a terrifying dragon, as presented by the creature’s plucky kobold assistant. This 224-page hardcover rulebook presents a catalog of new gear from nearly every category of equipment and magic item available in the Pathfinder RPG while also introducing entirely new categories of items as well. Give your character the perfect tool for the job with signature weapons, customizable relics, and wondrous items to fit your every need while preparing for any eventuality with potions, elixirs, wands, and more!","require_key":false,"contact_info":null,"is_published":true,"required_content_sources":[1]},"patches":[{"table":"item","id":11937,"before":{"id":11937,"bulk":"","name":"Dragonclaw Scutcheon","size":"MEDIUM","uuid":"4742342761897748","group":"GENERAL","hands":null,"level":16,"price":{"gp":1600},"usage":"affixed to a shield","rarity":"COMMON","traits":[1531,1504,1544],"version":"1.0","meta_data":{"hp":0,"bulk":{},"group":"","runes":{},"damage":{},"hp_max":0,"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=4634","book":"Treasure Vault","page":"92"},"charges":{},"foundry":{"items":[],"rules":[],"container_id":null},"hardness":0,"material":{"type":null,"grade":null},"quantity":1,"base_item":null,"image_url":"","is_shoddy":false,"starfinder":{},"unselectable":false,"broken_threshold":0},"created_at":"2024-04-19T04:16:34.576952+00:00","operations":null,"description":"**Activate** <abbr cost=\"FREE-ACTION\" class=\"action-symbol\">4</abbr> ([concentrate](link_trait_1432)) **Requirements** You have the affixed shield [raised](link_action_19750); **Trigger** You would take damage of a type depending on the [talisman](link_trait_1544)’s [dragon](link_trait_2402) type.\n\n* * *\n\nThis decorative shield emblem contains the gilded claw of a [dragon](link_trait_2402) mounted in a setting of high-grade adamantine alloy. It protects against a damage type depending on the type of [dragon](link_trait_2402) the claw came from (see below). When you Activate the scutcheon, you and all of your carried, wielded, or worn items gain immunity to all damage of that type until the end of your next turn.\n\nIf you have a _[dragonclaw scutcheon](link_item_11937)_, _[dragonscale cameo](link_item_11941)_, and _[dragontooth trophy](link_item_11944)_ attached to your items, and they all correspond to the same type of [dragon](link_trait_2402), you gain an extra benefit. When you Activate any of these [talismans](link_trait_1544), you gain the ability to cast an 8th-rank, DC 35 *[dragon breath](link_spell_6435)* focus spell as an innate spell once before the end of your next turn. Use the [dragon](link_trait_2402) type that matches the [talismans](link_trait_1544); you can Cast the Spell this way without spending a [Focus Point](link_trait_1856). Because each [talisman](link_trait_1544) disintegrates when used, you can’t get this benefit again until you’ve attached a replacement.\n\n* * *\n\n#### Dragon Damage Types\n\nThe _[dragonclaw scutcheon](link_item_11937)_ and _[dragontooth trophy](link_item_11944)_ use a type of damage depending on what kind of [dragon](link_trait_2402) the claw or tooth came from. These items are typically made from the [dragons](link_trait_2402) in Monster Core, but your GM might introduce uncommon or rare versions made from other types of [dragons](link_trait_2402).\n\n| Dragon Type | Damage Type |\n\n| --- | --- |\n\n| Adamantine | Bludgeoning |\n\n| Conspirator or horned | [Poison](link_trait_1476) |\n\n| Diabolic | [Fire](link_trait_1542) |\n\n| Empyreal | [Spirit](link_trait_1556) |\n\n| Fortune | [Force](link_trait_1560) |\n\n| Mirage or omen | [Mental](link_trait_1448) |","availability":null,"content_source_id":16,"craft_requirements":"Supply one claw from an adult or older dragon."},"after":{"id":11937,"bulk":"","name":"Dragonclaw Scutcheon","size":"MEDIUM","uuid":"4742342761897748","group":"GENERAL","hands":null,"level":16,"price":{"gp":1600},"usage":"affixed to a shield","rarity":"COMMON","traits":[1531,1504,1544],"version":"1.0","meta_data":{"hp":0,"bulk":{},"group":"","runes":{},"damage":{},"hp_max":0,"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=4634","book":"Treasure Vault","page":"92"},"charges":{},"foundry":{"items":[],"rules":[],"container_id":null},"hardness":0,"material":{"type":null,"grade":null},"quantity":1,"base_item":null,"image_url":"","is_shoddy":false,"starfinder":{},"unselectable":false,"broken_threshold":0},"created_at":"2024-04-19T04:16:34.576952+00:00","operations":null,"description":"**Activate** <abbr cost=\"FREE-ACTION\" class=\"action-symbol\">4</abbr> ([concentrate](link_trait_1432)) **Requirements** You have the affixed shield [raised](link_action_19750); **Trigger** You would take damage of a type depending on the [talisman](link_trait_1544)’s [dragon](link_trait_2402) type.\n\n* * *\n\nThis decorative shield emblem contains the gilded claw of a [dragon](link_trait_2402) mounted in a setting of high-grade adamantine alloy. It protects against a damage type depending on the type of [dragon](link_trait_2402) the claw came from (see below). When you Activate the scutcheon, you and all of your carried, wielded, or worn items gain immunity to all damage of that type until the end of your next turn.\n\nIf you have a _[dragonclaw scutcheon](link_item_11937)_, _[dragonscale cameo](link_item_11941)_, and _[dragontooth trophy](link_item_11944)_ attached to your items, and they all correspond to the same type of [dragon](link_trait_2402), you gain an extra benefit. When you Activate any of these [talismans](link_trait_1544), you gain the ability to cast an 8th-rank, DC 35 *[dragon breath](link_spell_6435)* focus spell as an innate spell once before the end of your next turn. Use the [dragon](link_trait_2402) type that matches the [talismans](link_trait_1544); you can Cast the Spell this way without spending a [Focus Point](link_trait_1856). Because each [talisman](link_trait_1544) disintegrates when used, you can’t get this benefit again until you’ve attached a replacement.\n\n* * *\n\n#### Dragon Damage Types\n\nThe _[dragonclaw scutcheon](link_item_11937)_ and _[dragontooth trophy](link_item_11944)_ use a type of damage depending on what kind of [dragon](link_trait_2402) the claw or tooth came from. These items are typically made from the [dragons](link_trait_2402) in Monster Core, but your GM might introduce uncommon or rare versions made from other types of [dragons](link_trait_2402).\n\n| Dragon Type | Damage Type |\n\n| --- | --- |\n\n| Adamantine | Bludgeoning |\n\n| Conspirator or horned | Bludgeoning |\n\n| Diabolic | [Fire](link_trait_1542) |\n\n| Empyreal | [Spirit](link_trait_1556) |\n\n| Fortune | [Force](link_trait_1560) |\n\n| Mirage or omen | [Mental](link_trait_1448) |","availability":null,"content_source_id":16,"craft_requirements":"Supply one claw from an adult or older dragon."}},{"table":"item","id":11944,"before":{"id":11944,"bulk":"0","name":"Dragontooth Trophy","size":"MEDIUM","uuid":"2341035386880611","group":"GENERAL","hands":null,"level":14,"price":{"gp":800},"usage":"affixed to a weapon","rarity":"COMMON","traits":[1531,1504,1544],"version":"1.0","meta_data":{"hp":0,"bulk":{},"group":"","runes":{},"damage":{},"hp_max":0,"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=4636","book":"Treasure Vault","page":"93"},"charges":{},"foundry":{"items":[],"rules":[],"container_id":null},"hardness":0,"material":{"type":null,"grade":null},"quantity":1,"base_item":null,"image_url":"","is_shoddy":false,"starfinder":{},"unselectable":false,"broken_threshold":0},"created_at":"2024-04-19T04:16:40.084809+00:00","operations":null,"description":"**Activate** <abbr cost=\"FREE-ACTION\" class=\"action-symbol\">4</abbr> ([concentrate](link_trait_1432)) **Trigger** You succeed at a [Strike](link_action_19856) with the affixed weapon.\n\n* * *\n\nThis imposing fang is engraved with an intricate arrangement of symbols, glyphs, and patterns and dangles from a leather strap bound to the hilt of the affixed weapon. When you Activate the trophy, your weapon is momentarily transformed into a magical construct of draconic fury. On the triggering [Strike](link_action_19856) and until the end of your next turn, the damage type of the affixed weapon changes to the type matching the [dragon](link_trait_2402) the claw came from (see below). This change overrides the versatile trait and similar abilities.\n\n* * *\n\n#### Dragon Damage Types\n\nThe _[dragonclaw scutcheon](link_item_11937)_ and _[dragontooth trophy](link_item_11944)_ use a type of damage depending on what kind of [dragon](link_trait_2402) the claw or tooth came from. These items are typically made from the [dragons](link_trait_2402) in Monster Core, but your GM might introduce uncommon or rare versions made from other types of [dragons](link_trait_2402).\n\n| Dragon Type | Damage Type |\n\n| --- | --- |\n\n| Adamantine | Bludgeoning |\n\n| Conspirator or horned | [Poison](link_trait_1476) |\n\n| Diabolic | [Fire](link_trait_1542) |\n\n| Empyreal | [Spirit](link_trait_1556) |\n\n| Fortune | [Force](link_trait_1560) |\n\n| Mirage or omen | [Mental](link_trait_1448) |","availability":null,"content_source_id":16,"craft_requirements":"Supply one tooth from an adult or older dragon."},"after":{"id":11944,"bulk":"0","name":"Dragontooth Trophy","size":"MEDIUM","uuid":"2341035386880611","group":"GENERAL","hands":null,"level":14,"price":{"gp":800},"usage":"affixed to a weapon","rarity":"COMMON","traits":[1531,1504,1544],"version":"1.0","meta_data":{"hp":0,"bulk":{},"group":"","runes":{},"damage":{},"hp_max":0,"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=4636","book":"Treasure Vault","page":"93"},"charges":{},"foundry":{"items":[],"rules":[],"container_id":null},"hardness":0,"material":{"type":null,"grade":null},"quantity":1,"base_item":null,"image_url":"","is_shoddy":false,"starfinder":{},"unselectable":false,"broken_threshold":0},"created_at":"2024-04-19T04:16:40.084809+00:00","operations":null,"description":"**Activate** <abbr cost=\"FREE-ACTION\" class=\"action-symbol\">4</abbr> ([concentrate](link_trait_1432)) **Trigger** You succeed at a [Strike](link_action_19856) with the affixed weapon.\n\n* * *\n\nThis imposing fang is engraved with an intricate arrangement of symbols, glyphs, and patterns and dangles from a leather strap bound to the hilt of the affixed weapon. When you Activate the trophy, your weapon is momentarily transformed into a magical construct of draconic fury. On the triggering [Strike](link_action_19856) and until the end of your next turn, the damage type of the affixed weapon changes to the type matching the [dragon](link_trait_2402) the claw came from (see below). This change overrides the versatile trait and similar abilities.\n\n* * *\n\n#### Dragon Damage Types\n\nThe _[dragonclaw scutcheon](link_item_11937)_ and _[dragontooth trophy](link_item_11944)_ use a type of damage depending on what kind of [dragon](link_trait_2402) the claw or tooth came from. These items are typically made from the [dragons](link_trait_2402) in Monster Core, but your GM might introduce uncommon or rare versions made from other types of [dragons](link_trait_2402).\n\n| Dragon Type | Damage Type |\n\n| --- | --- |\n\n| Adamantine | Bludgeoning |\n\n| Conspirator or horned | Bludgeoning |\n\n| Diabolic | [Fire](link_trait_1542) |\n\n| Empyreal | [Spirit](link_trait_1556) |\n\n| Fortune | [Force](link_trait_1560) |\n\n| Mirage or omen | [Mental](link_trait_1448) |","availability":null,"content_source_id":16,"craft_requirements":"Supply one tooth from an adult or older dragon."}},{"table":"item","id":12325,"before":{"id":12325,"bulk":"0","name":"Resonating Fork (Major)","size":"MEDIUM","uuid":"2307628812193819","group":"GENERAL","hands":null,"level":12,"price":{"gp":1800},"usage":"affixed to armor or a weapon","rarity":"COMMON","traits":[1504,1484,2570],"version":"1.0","meta_data":{"hp":0,"bulk":{},"group":"","runes":{},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":0,"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=4771","book":"Treasure Vault","page":"128"},"charges":{},"foundry":{"items":[],"rules":[],"container_id":null},"category":"","hardness":0,"material":{"type":null,"grade":null},"quantity":1,"base_item":null,"image_url":"","is_shoddy":false,"starfinder":{},"unselectable":false,"broken_threshold":0,"spellheart_casting":{"dc":29}},"created_at":"2024-04-19T04:21:31.489653+00:00","operations":null,"description":"This two-pronged fork of metal emits a constant low hum, vibrating slightly when touched. The spell attack roll of any spell cast by Activating this item is +13, and the spell DC is 29.\n\n*   **Armor** You gain resistance 10 to [sonic](link_trait_1484) damage and a +2 item bonus to saving throws against effects with the [auditory](link_trait_1469) or [sonic](link_trait_1484) trait.\n    \n*   **Weapon** After you cast a [sonic](link_trait_1484) spell by activating the fork, the weapon reverberates with trapped sound waves. Your next [Strike](link_action_19856) causes the target to be deafened for 1 minute if it hits (or for 1 hour on a critical hit). If you don't make a [Strike](link_action_19856) by the end of your next turn, the sound waves dissipate with no effect.\n    \n\n**Activate** [Cast a Spell](link_action_19611); **Effect** You cast *[bullhorn](link_spell_6722)*.\n\n**Activate** [Cast a Spell](link_action_19611); **Frequency** once per day; **Effect** You cast 4th-rank *[noise blast](link_spell_4742)*.\n\n**Activate** [Cast a Spell](link_action_19611); **Frequency** once per day; **Effect** You cast *[painful vibrations](link_spell_8995)*.","availability":null,"content_source_id":16,"craft_requirements":null},"after":{"id":12325,"bulk":"0","name":"Resonating Fork (Major)","size":"MEDIUM","uuid":"2307628812193819","group":"GENERAL","hands":null,"level":12,"price":{"gp":1800},"usage":"affixed to armor or a weapon","rarity":"COMMON","traits":[1504,1484,2570],"version":"1.0","meta_data":{"hp":0,"bulk":{},"group":"","runes":{},"damage":{"die":"","dice":"","extra":"","damageType":""},"hp_max":0,"source":{"url":"https://2e.aonprd.com/Equipment.aspx?ID=4771","book":"Treasure Vault","page":"128"},"charges":{},"foundry":{"items":[],"rules":[],"container_id":null},"category":"","hardness":0,"material":{"type":null,"grade":null},"quantity":1,"base_item":null,"image_url":"","is_shoddy":false,"starfinder":{},"unselectable":false,"broken_threshold":0,"spellheart_casting":{"dc":29,"attack":19}},"created_at":"2024-04-19T04:21:31.489653+00:00","operations":null,"description":"This two-pronged fork of metal emits a constant low hum, vibrating slightly when touched. The spell attack roll of any spell cast by Activating this item is +19, and the spell DC is 29.\n\n*   **Armor** You gain resistance 10 to [sonic](link_trait_1484) damage and a +2 item bonus to saving throws against effects with the [auditory](link_trait_1469) or [sonic](link_trait_1484) trait.\n    \n*   **Weapon** After you cast a [sonic](link_trait_1484) spell by activating the fork, the weapon reverberates with trapped sound waves. Your next [Strike](link_action_19856) causes the target to be deafened for 1 minute if it hits (or for 1 hour on a critical hit). If you don't make a [Strike](link_action_19856) by the end of your next turn, the sound waves dissipate with no effect.\n    \n\n**Activate** [Cast a Spell](link_action_19611); **Effect** You cast *[bullhorn](link_spell_6722)*.\n\n**Activate** [Cast a Spell](link_action_19611); **Frequency** once per day; **Effect** You cast 4th-rank *[noise blast](link_spell_4742)*.\n\n**Activate** [Cast a Spell](link_action_19611); **Frequency** once per day; **Effect** You cast *[painful vibrations](link_spell_8995)*.","availability":null,"content_source_id":16,"craft_requirements":null}}]}$source_corrections102$::jsonb as spec)
select 'treasure-vault-source-corrections' as id, coalesce(
  exists (select 1 from public.content_source s where s.id=16 and (to_jsonb(s)-'updated_at')=spec->'source')
  and not exists (select 1 from jsonb_array_elements(spec->'patches') p left join public.item i on i.id=(p->>'id')::bigint where ((to_jsonb(i)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',i.uuid::text)) is distinct from p->'after')
  and not exists (select 1 from public.content_update u where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in ('APPROVED','REJECTED') and (
  (u.type='item' and exists (select 1 from jsonb_array_elements(spec->'patches') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or u.data->>'uuid'=p#>>'{before,uuid}'
    or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{before,name}')))
    or (coalesce(btrim(u.data#>>'{meta_data,source,url}'),'')<>'' and lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(p#>>'{before,meta_data,source,url}')))))
  or (u.type='content-source' and (u.ref_id=16 or u.data->>'id'='16' or lower(btrim(u.data->>'name'))='treasure vault')))),false) as passed from settings;
